module alu8(a, b, op, result, zero, carry);
  input  [7:0] a;
  input  [7:0] b;
  input  [2:0] op;
  output [7:0] result;
  output zero;
  output carry;

  reg [7:0] result_r;
  reg       carry_r;

  wire [8:0] add_ext = {1'b0, a} + {1'b0, b};
  wire [8:0] sub_ext = {1'b0, a} - {1'b0, b};

  always @* begin
    result_r = 8'b00000000;
    carry_r  = 1'b0;

    case (op)
      3'b000: begin
        result_r = add_ext[7:0];   // add
        carry_r  = add_ext[8];     // carry out
      end

      3'b001: begin
        result_r = sub_ext[7:0];   // subtract: a - b
        carry_r  = sub_ext[8];     // borrow out
      end

      3'b010: begin
        result_r = a & b;
        carry_r  = 1'b0;
      end

      3'b011: begin
        result_r = a | b;
        carry_r  = 1'b0;
      end

      3'b100: begin
        result_r = a ^ b;
        carry_r  = 1'b0;
      end

      3'b101: begin
        result_r = ~a;
        carry_r  = 1'b0;
      end

      3'b110: begin
        result_r = {a[6:0], 1'b0}; // logical shift left by 1
        carry_r  = 1'b0;
      end

      3'b111: begin
        result_r = {1'b0, a[7:1]}; // logical shift right by 1
        carry_r  = 1'b0;
      end
    endcase
  end

  assign result = result_r;
  assign carry  = carry_r;
  assign zero   = (result_r == 8'b00000000);

endmodule

